INSERT INTO `table_product` (`id`, `id_list`, `id_item`, `id_cat`, `id_sub`, `id_brand`, `photo`, `options`, `slugvi`, `slugen`, `contenten`, `contentvi`, `descen`, `descvi`, `nameen`, `namevi`, `code`, `regular_price`, `discount`, `sale_price`, `numb`, `status`, `type`, `date_created`, `date_updated`, `view`, `tietkiem`, `thongsovi`, `thongsoen`, `option_size`, `dungluongvi`, `dungluongen`, `link_youtube`, `gialendoi`, `giadukien`) VALUES
(56, 7, 5, 10, 0, 0, 'iphone-14-3-1499.jpg', '{\"p\":\"iphone-14-3-1499.jpg\",\"w\":600,\"h\":600,\"m\":\"image\\/jpeg\"}', 'iphone-14-128gb-chinh-hang-apple', '', '', '&lt;h1&gt;&lt;strong&gt;iPhone 14 – 128GB | Chính Hãng Apple&lt;/strong&gt;&lt;/h1&gt;\r\n\r\n&lt;h3&gt;Sau bao khoảng thời gian dài chờ đợi thì vào ngày 08/09 chiếc điện thoại &lt;a href=&quot;https://ldlphones.com.vn/iphone-14/&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot; title=&quot;Tham khảo điện thoại đang kinh doanh tại Thế Giới Di Động&quot;&gt;iPhone 14&lt;/a&gt; cũng đã chính thức được lộ diện, với hàng loạt thông số kỹ thuật ấn tượng từ camera cho đến hiệu năng cực khủng. Hứa hẹn sẽ trở thành tâm điểm gây chú ý nhất của nửa cuối năm 2022.&lt;/h3&gt;\r\n\r\n&lt;h3&gt;Hoàn thiện cao cấp sang trọng&lt;/h3&gt;\r\n\r\n&lt;p&gt;iPhone 14 128GB được hoàn thiện với ngoại hình vuông vức khi hai cạnh và các mặt vát phẳng, đây được xem là kiểu thiết kế thời thượng và được cộng đồng người dùng đón nhận rất tích cực kể từ thế hệ iPhone 12 cho đến nay.&lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034242.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;iPhone 14 - 128GB | Chính Hãng Apple&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034242.jpg&quot; decoding=&quot;async&quot; height=&quot;570&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034242.jpg&quot; title=&quot;Thiết kế sang trọng - iPhone 14 128GB&quot; width=&quot;1020&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;Hoàn thiện từ vật liệu cao cấp với mặt lưng kính cùng bộ khung nhôm giúp máy toát lên được vẻ ngoài đẳng cấp, giúp bạn có thể trở nên nổi bật hơn khi cầm nắm sản phẩm trên tay.&lt;/p&gt;\r\n\r\n&lt;p&gt;Apple mang đến cho người dùng 5 loại màu sắc: Đen, Trắng, Xanh Dương, Đỏ, Tím nhạt với những màu này bạn sẽ dễ dàng lựa chọn được mẫu điện thoại ưng ý nhất với mình và phù hợp với phong cách khác nhau.&lt;/p&gt;\r\n\r\n&lt;h3&gt;Giải trí đã mắt hơn trên màn hình chất lượng&lt;/h3&gt;\r\n\r\n&lt;p&gt;Về phần hiển thị thì máy sẽ trang bị tấm nền OLED có công nghệ Super Retina XDR cao cấp, với khả năng hiển thị màu sắc có độ chính xác cao giúp bạn có thể an tâm hơn trên các tác vụ chỉnh sửa và sản xuất những nội dung đồ họa.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034244.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Tấm nền OLED chất lượng - iPhone 14 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034244.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034244.jpg&quot; title=&quot;Tấm nền OLED chất lượng - iPhone 14 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;Ngoài ra các tác vụ chơi game hay xem phim cũng sẽ trở nên đã mắt hơn, giúp bạn có thể chiêm ngưỡng được trọn vẹn mọi nội dung mà sản xuất mang đến cho người dùng.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034246.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Màu chắc chân thực - iPhone 14 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034246.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034246.jpg&quot; title=&quot;Màu chắc chân thực - iPhone 14 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;h3&gt;Tích hợp bộ đôi camera chất lượng&lt;/h3&gt;\r\n\r\n&lt;p&gt;Lần này Apple mang đến cho người là một chiếc điện thoại có 2 camera có chung độ phân giải 12 MP. Đi kèm với đó sẽ là hàng loạt các tính năng mới giúp bạn có thể thỏa sức nhiếp ảnh một cách đầy nghệ thuật.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034250.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Trang bị camera đôi - iPhone 14 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034250.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034250.jpg&quot; title=&quot;Trang bị camera đôi - iPhone 14 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;Cùng với khả năng xử lý hình ảnh thông minh nhờ sự nâng cấp thuật toán trên chipset, giúp máy có thể xử lý màu sắc trung thực hơn hay nâng cao chất lượng trên các bức ảnh chụp đêm. Chế độ quay điện ảnh tự động chuyển tiêu điểm đến chủ thể quan trọng nhất trong một cảnh ở định dạng 4K, mang đến cho bạn những video ấn tượng nhất.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034252.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Nâng cao khả năng xử lý hình ảnh - iPhone 14 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034252.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034252.jpg&quot; title=&quot;Nâng cao khả năng xử lý hình ảnh - iPhone 14 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;Máy có hỗ trợ chế độ quay video đạt chuẩn lên đến 4K sắc nét, được xem là điều cực kỳ hữu ích đối với người dùng đam mê quay phim hay đang làm những công việc sản xuất nội dung trên những nền tảng mạng xã hội.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034255.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Hỗ trợ quay phim sắc nét - iPhone 14 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034255.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034255.jpg&quot; title=&quot;Hỗ trợ quay phim sắc nét - iPhone 14 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;Camera trước 12 MP TrueDepth được trang bị thêm tính năng lấy nét tự động và có khẩu độ lớn hơn.&lt;/p&gt;\r\n\r\n&lt;h3&gt;Hiệu năng hàng đầu thế giới&lt;/h3&gt;\r\n\r\n&lt;p&gt;Như thường lệ mỗi lần nhà Apple ra mắt sản phẩm mới đều đem đến cho thị trường một con chip có hiệu năng cực khủng, điều này cũng không là ngoại lệ với chiếc điện thoại iPhone 14 khi được trang bị bộ vi xử lý Apple A15 Bionic 6 nhân.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034256.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Chipset hiệu năng cao - iPhone 14 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034256.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034256.jpg&quot; title=&quot;Chipset hiệu năng cao - iPhone 14 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;Đây là vi xử lý trang bị trên iPhone 13 series, vẫn là một sức mạnh có thể giúp bạn xử lý tốt mọi nhu cầu tác vụ từ xử lý nội dung video hay hỗ trợ chơi được nhiều tựa game đồ họa cao mượt mà. Điện thoại chạy trên nền tảng iOS 16 cho phép bạn tùy chỉnh màn hình khóa và có một giao diện thân thiện hơn.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034259.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Chipset hiệu năng cao - iPhone 14 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034259.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/240259/iphone-14-080922-034259.jpg&quot; title=&quot;Chipset hiệu năng cao - iPhone 14 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;Viên pin cũng được nâng cấp thời lượng sử dụng khi máy cho phép bạn xem video 20 giờ liên tục.&lt;/p&gt;\r\n\r\n&lt;h3&gt;Giá bán dự kiến của iPhone 14 là bao nhiêu&lt;/h3&gt;\r\n\r\n&lt;p&gt;Nếu bạn quan tâm đến giá của iPhone 14 thì hiện tại iPhone 14 với 3 mức dung lượng khác nhau phù hợp với nhu cầu của từng khách hàng, tại Thế Giới Di Động bạn có thể đăng ký nhận nhận thông tin khi hàng về với giá dự kiến:&lt;/p&gt;\r\n\r\n&lt;ul&gt;\r\n	&lt;li&gt;&lt;a href=&quot;https://ldlphones.com.vn/iphone-14-128gb-chinh-hang/&quot;&gt;iPhone 14 128GB:&lt;/a&gt; 24.990.000đ&lt;/li&gt;\r\n	&lt;li&gt;&lt;a href=&quot;https://ldlphones.com.vn/iphone-14-256gb-chinh-hang/&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot; title=&quot;Tham khảo mẫu điện thoại iPhone 14 256GB đang kinh doanh tại Thế Giới Di Động &quot;&gt;iPhone 14 256GB&lt;/a&gt;: 27.990.000đ&lt;/li&gt;\r\n	&lt;li&gt;&lt;a href=&quot;https://ldlphones.com.vn/iphone-14-512gb-chinh-hang/&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot; title=&quot;Tham khảo điện thoại iPhone 14 512GB đang kinh doanh tại Thế Giới Di Động &quot;&gt;iPhone 14 512GB&lt;/a&gt;: 33.990.000đ&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;p&gt;Với những điều hết sức tuyệt vời trên iPhone 14 128GB mang lại, đây chắc chắn sẽ trở thành một trong những chiếc &lt;a href=&quot;https://ldlphones.com.vn/iphone/&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot; title=&quot;Tham khảo điện thoại đang kinh doanh tại Thế Giới Di Động&quot;&gt;điện thoại iPhone&lt;/a&gt; đáng mua nhất năm 2022. Không đơn thuần là một smartphone mà đây còn là một món phụ kiện cao cấp giúp bạn toát lên được vẻ ngoài hào nhoáng sang trọng khi cầm nắm trên tay.&lt;/p&gt;\r\n', '', '&lt;p&gt;☑️ Máy New Fullbox – Chưa Active – Chính Hãng Apple&lt;/p&gt;\r\n\r\n&lt;p&gt;☑️ Hỗ trợ 1 đổi 1 trong 30 ngày nếu có lỗi từ NSX&lt;/p&gt;\r\n\r\n&lt;p&gt;☑️ Bảo hành chính hãng Apple 12 tháng&lt;/p&gt;\r\n\r\n&lt;p&gt;☑️ Cài Đặt ứng dụng miễn phí và phần mềm.&lt;/p&gt;\r\n', '', 'iPhone 14 – 128GB | Chính Hãng Apple ', '', 18790000, 1, 18590000, 1, 'keothom,linew,noibat,hienthi', 'san-pham', 1689780599, 1694850272, 485, 0, '', '', '{\"19\":{\"regular_price\":\"18790000\",\"sale_price\":\"0\",\"discount\":0,\"id_size\":\"19\",\"photo_price\":\"iphone-14-8.jpeg\"},\"18\":{\"regular_price\":\"18790000\",\"sale_price\":\"0\",\"discount\":0,\"id_size\":\"18\",\"photo_price\":\"iphone-14-3.jpeg\"},\"17\":{\"regular_price\":\"18790000\",\"sale_price\":\"0\",\"discount\":0,\"id_size\":\"17\",\"photo_price\":\"iphone-14-5.jpeg\"},\"16\":{\"regular_price\":\"18790000\",\"sale_price\":\"0\",\"discount\":0,\"id_size\":\"16\",\"photo_price\":\"iphone-14-9.jpeg\"},\"15\":{\"regular_price\":\"18790000\",\"sale_price\":\"0\",\"discount\":0,\"id_size\":\"15\",\"photo_price\":\"iphone-14-6.jpeg\"},\"13\":{\"regular_price\":\"18790000\",\"sale_price\":\"0\",\"discount\":0,\"id_size\":\"13\",\"photo_price\":\"iphone-14-4.jpeg\"}}', '128GB', '', '', 0, NULL),
(68, 7, 6, 10, 0, 0, '14-plus-tim-6693.jpeg', '{\"p\":\"14-plus-tim-6693.jpeg\",\"w\":600,\"h\":600,\"m\":\"image\\/jpeg\"}', 'iphone-14-plus-128gb-chinh-hang-apple', '', '', '&lt;h1&gt;&lt;strong&gt;iPhone 14 Plus – 128GB | Chính Hãng Apple&lt;/strong&gt;&lt;/h1&gt;\r\n\r\n&lt;h3&gt;&lt;a href=&quot;https://ldlphones.com.vn/iphone-14-plus/&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot; title=&quot;Tham khảo điện thoại đang kinh doanh tại Thế Giới Di Động&quot;&gt;iPhone 14 Plus&lt;/a&gt; thu hút mọi ánh nhìn trong sự kiện Far Out diễn ra ngày 8/9 nhờ có vẻ ngoài cao cấp, trang bị bộ xử lý mạnh mẽ, cụm camera kép đặc trưng cho khả năng chụp ảnh cực nét cùng màn hình chất lượng cao cho bạn tận hưởng cảm giác sử dụng smartphone tuyệt vời hơn.&lt;/h3&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;h3&gt;Thiết kế nguyên khối, hiện đại&lt;/h3&gt;\r\n\r\n&lt;p&gt;iPhone 14 Plus được chế tác với kiểu dáng tương tự như thế hệ tiền nhiệm &lt;a href=&quot;https://ldlphones.com.vn/iphone-13-series/&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot; title=&quot;Tham khảo iPhone 13 tại Thế Giới Di Động&quot;&gt;iPhone 13&lt;/a&gt;, tinh tế theo từng đường nét với khung nhôm chắc chắn, mặt trước và sau được trang bị kính cường lực vừa tăng tính thẩm mỹ vừa tăng độ bền cho thiết bị.&lt;/p&gt;\r\n\r\n&lt;p&gt;Màu sắc là phần luôn được đổi mới ở các thế hệ iPhone, mỗi dòng thường sẽ có 1 màu sắc đặc biệt ghi dấu ấn riêng. iPhone 14 năm nay sẽ có 5 màu với tone dịu nhẹ như: Đen, trắng, xanh dương, tím nhạt và đỏ. Các màu đều mang một phong cách trẻ trung, phù hợp với hầu như tất cả mọi phong cách người dùng.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111102.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;iPhone 14 Plus - 128GB | Chính Hãng Apple&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111102.jpg&quot; decoding=&quot;async&quot; height=&quot;570&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111102.jpg&quot; title=&quot;Thiết kế cao cấp - iPhone 14 Plus 128GB&quot; width=&quot;1020&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;Đây được xem là phiên bản phóng to của &lt;a href=&quot;https://ldlphones.com.vn/iphone-14/&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot; title=&quot;Tham khảo điện thoại đang kinh doanh tại Thế Giới Di Động&quot;&gt;iPhone 14&lt;/a&gt; nhằm đem đến cho người dùng một thiết bị có thiết kế lớn hơn, đem đến trải nghiệm giải trí tuyệt vời khi có không gian hiển thị rộng rãi.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111105.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Ngoại hình sang trọng - iPhone 14 Plus 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111105.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111105.jpg&quot; title=&quot;Ngoại hình sang trọng - iPhone 14 Plus 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;h3&gt;Màn hình sắc nét, trọn vẹn giải trí&lt;/h3&gt;\r\n\r\n&lt;p&gt;iPhone 14 Plus có một màn hình Super Retina XDR siêu lớn và tấm nền OLED cho chất lượng hình ảnh cao, màu sắc hiển thị chính xác để bất kỳ thứ gì hiển thị trên màn hình đều trở nên sinh động, tự nhiên và sắc nét.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111107.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Màn hình chất lượng - iPhone 14 Plus 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111107.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111107.jpg&quot; title=&quot;Màn hình chất lượng - iPhone 14 Plus 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;Với màn hình lên đến 6.7 inch nên mọi chi tiết trên màn ảnh đều được tái hiện to rõ, thích hợp cho những bạn thiết kế và chỉnh sửa ấn phẩm đồ họa trên điện thoại iPhone nhờ không gian thao tác rộng rãi.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111104.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Hình ảnh to rõ - iPhone 14 Plus 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111104.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111104.jpg&quot; title=&quot;Hình ảnh to rõ - iPhone 14 Plus 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;h3&gt;Camera chụp ảnh chuyên nghiệp&lt;/h3&gt;\r\n\r\n&lt;p&gt;iPhone 14 Plus được nâng cấp khả năng xử lý hình ảnh trên bộ đôi camera sau 12 MP, mang lại chất lượng chụp ảnh ấn tượng giúp người dùng có thể thoải mái sáng tạo và nhiếp ảnh để có cho mình những bức ảnh nghệ thuật theo ý thích.&lt;/p&gt;\r\n\r\n&lt;p&gt;Với những nâng cấp về thuật toán, camera trên iPhone 14 Plus sẽ mang đến khả năng xử lý hình ảnh được cải tiến, đặc biệt là trong môi trường ánh sáng yếu.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111108.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Camera đôi chất lượng - iPhone 14 Plus 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111108.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111108.jpg&quot; title=&quot;Camera đôi chất lượng - iPhone 14 Plus 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;Camera trước của điện thoại vẫn nằm trong cụm tai thỏ quen thuộc, độ phân giải cũng đạt 12 MP cùng hàng loạt các công nghệ chụp ảnh chuyên nghiệp để bạn tự tin thể hiện mình trước ống kính.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111112.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Selfie chất lượng - iPhone 14 Plus 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111112.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111112.jpg&quot; title=&quot;Selfie chất lượng - iPhone 14 Plus 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;h3&gt;Hiệu năng của quái vật&lt;/h3&gt;\r\n\r\n&lt;p&gt;iPhone 14 Plus mang trong mình sức mạnh của bộ vi xử lý A15 Bionic, được xem là cái tên làm mưa làm gió về hiệu năng trong năm 2021 nên người dùng hoàn toàn có thể an tâm rằng máy có thể đáp ứng mọi nhu cầu từ chơi game tới xử lý công việc cho 2 – 3 năm tiếp theo.&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111115.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Hiệu năng mạnh mẽ - iPhone 14 Plus 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111115.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111115.jpg&quot; title=&quot;Hiệu năng mạnh mẽ - iPhone 14 Plus 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;iPhone 14 Plus sử dụng hệ điều hành iOS 16 với nhiều sự thay đổi mạnh mẽ về màn hình khóa, có nhiều tính năng thú vị như: Tách chủ thể ra khỏi nền ở ứng dụng ảnh, mở khóa FaceID khi đặt máy nằm ngang,…&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;a href=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111114.jpg&quot; rel=&quot;noopener&quot; target=&quot;_blank&quot;&gt;&lt;img alt=&quot;Thỏa sức chiến game - iPhone 14 Plus 128GB&quot; data-src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111114.jpg&quot; decoding=&quot;async&quot; src=&quot;https://cdn.tgdd.vn/Products/Images/42/245545/iphone-14-max-080922-111114.jpg&quot; title=&quot;Thỏa sức chiến game - iPhone 14 Plus 128GB&quot; /&gt;&lt;/a&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt; &lt;/p&gt;\r\n\r\n&lt;h3&gt;Thời lượng sử dụng pin lâu hơn&lt;/h3&gt;\r\n\r\n&lt;p&gt;Pin là phần được rất nhiều người dùng quan tâm trên những chiếc iPhone, với sự tối ưu về phần mềm iPhone 14 Plus sẽ mang đến thời gian sử dụng lên đến ~26 giờ* khi xem video. Thời gian sử dụng này bạn có thể an tâm sử dụng máy trong một ngày.&lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;i&gt;*Thông tin Apple công bố&lt;/i&gt;&lt;/p&gt;\r\n', '', '&lt;p&gt;☑️ Máy New Fullbox – Chưa Active – Chính Hãng Apple&lt;/p&gt;\r\n\r\n&lt;p&gt;☑️ Hỗ trợ 1 đổi 1 trong 30 ngày nếu có lỗi từ NSX&lt;/p&gt;\r\n\r\n&lt;p&gt;☑️ Bảo hành chính hãng Apple 12 tháng&lt;/p&gt;\r\n\r\n&lt;p&gt;☑️ Cài Đặt ứng dụng miễn phí và phần mềm.&lt;/p&gt;\r\n', '', 'iPhone 14 Plus – 128GB | Chính Hãng Apple', '', 24444000, 23, 18900000, 1, 'hotsale,keothom,linew,noibat,hienthi', 'san-pham', 1689950713, 1701919931, 921, 0, '&lt;table&gt;\r\n	&lt;tbody&gt;\r\n		&lt;tr&gt;\r\n			&lt;th&gt;KÍCH THƯỚC MÀN HÌNH&lt;/th&gt;\r\n			&lt;td&gt;6.7 inches\r\n			&lt;p&gt;2778 x 1284 pixels&lt;/p&gt;\r\n			&lt;/td&gt;\r\n		&lt;/tr&gt;\r\n		&lt;tr&gt;\r\n			&lt;th&gt;CÔNG NGHỆ MÀN HÌNH&lt;/th&gt;\r\n			&lt;td&gt;OLED LPTS&lt;/td&gt;\r\n		&lt;/tr&gt;\r\n		&lt;tr&gt;\r\n			&lt;th&gt;TỐC ĐỘ LÀM MỚI&lt;/th&gt;\r\n			&lt;td&gt;60Hz&lt;/td&gt;\r\n		&lt;/tr&gt;\r\n		&lt;tr&g